using Fallout.Common.CI.GitHubActions;
using Fallout.Components;

// .github/workflows/build.yml is GENERATED from this attribute and regenerated by every build -
// change the attribute, never the YAML (AGENTS.md hard rule 4).
//
// One Linux job. FetchDepth = 0 because the changelog-driven version and GitRepository want the
// full history. SmokeTest implies PublishAot, so CI publishes a real linux-x64 Native AOT binary
// and speaks JSON-RPC to it on every push and pull request.
//
// CLAUDE_ROSLYN_LSP_LIVE_TESTS is set for the whole job, which turns on both halves of the live
// path: the opt-in xunit tests in tests/**/Live/ and the LiveTest target, which drives the
// published binary against the fixture solution and a real downloaded Roslyn. That download is
// about 70 MB per run and is worth it here and nowhere else - it is the only check in CI that
// Microsoft's server still answers what this adapter believes it answers, and the WP4 run that
// added it found a bug (C48) that every scripted test had passed.
//
// RoslynServerManifest.cs joins the cache key because it carries the pinned version and its
// hashes: a pin bump has to miss the cache, or the job would test the new pin against the old
// payload.
//
// PublishArtifacts = false: the per-RID archives that PublishAot .Produces() belong to the
// hand-written release workflow (the generator has no matrix support), not to the PR gate.
[GitHubActions(
    "build",
    GitHubActionsImage.UbuntuLatest,
    FetchDepth = 0,
    OnPushBranches = ["main"],
    OnPullRequestBranches = ["main"],
    ConcurrencyGroup = "${{ github.workflow }}-${{ github.ref }}",
    ConcurrencyCancelInProgress = true,
    InvokedTargets = [nameof(ITest.Test), nameof(SmokeTest), nameof(LiveTest)],
    CacheKeyFiles =
    [
        "**/global.json",
        "**/*.csproj",
        "**/Directory.Packages.props",
        "src/ClaudeRoslynLsp/Roslyn/RoslynServerManifest.cs",
    ],
    Env = ["CLAUDE_ROSLYN_LSP_LIVE_TESTS: 1"],
    PublishArtifacts = false)]
// .github/workflows/publish.yml is generated from this second attribute (same hard rule 4 - never
// hand-edit the YAML).
//
// The NuGet leg (D22) lives in its own workflow file because a nuget.org trusted publishing policy
// is scoped by workflow *file name* and the nuget.org UI offers no branch or tag filter. Keeping it
// out of build.yml is what stops an ordinary push from running a workflow that could mint a
// publishing key: only this file can, and only a v*.*.* tag can trigger it.
//
// No OnPushIncludePaths/ExcludePaths: a path filter alongside `tags:` evaluates over the tag
// commit's diff and can silently skip the release run. One Ubuntu job, because more jobs would mean
// more OIDC exchanges racing for the same one-key-per-30s rate limit.
[GitHubActions(
    "publish",
    GitHubActionsImage.UbuntuLatest,
    FetchDepth = 0,
    OnPushTags = ["v*.*.*"],
    CacheKeyFiles = [],
    InvokedTargets = [nameof(ICompile.Compile), nameof(ITest.Test), nameof(Pack), nameof(Publish)],
    PublishArtifacts = true,
    // The nuget.org profile name that created the trusted publishing policy. Public information and
    // deliberately not a secret - it goes verbatim into the token-exchange request body, and a
    // secret would be masked out of exactly the error message that names it.
    Env = ["NUGET_USER: lahma"],
    EnvironmentName = "nuget",
    ReadPermissions = [GitHubActionsPermissions.Contents],
    WritePermissions = [GitHubActionsPermissions.IdToken])]
partial class Build
{
}
